    Bug 1207366 - Allow setting the default sort column to all useful values. r=aleca

    This just updates the maximum allowed value for the preference, since new values have been added since it was written.

    Differential Revision: https://phabricator.services.mozilla.com/D236299

diff --git a/mailnews/db/msgdb/src/nsMsgDatabase.cpp b/mailnews/db/msgdb/src/nsMsgDatabase.cpp
index 33ce8ade2e0..19edcab9bdc 100644
--- a/mailnews/db/msgdb/src/nsMsgDatabase.cpp
+++ b/mailnews/db/msgdb/src/nsMsgDatabase.cpp
@@ -4915,7 +4915,8 @@ NS_IMETHODIMP nsMsgDatabase::GetDefaultSortType(
   NS_ENSURE_ARG_POINTER(aDefaultSortType);
   GetIntPref("mailnews.default_sort_type", aDefaultSortType);
   if (*aDefaultSortType < nsMsgViewSortType::byDate ||
-      *aDefaultSortType > nsMsgViewSortType::byAccount) {
+      *aDefaultSortType > nsMsgViewSortType::byCorrespondent ||
+      *aDefaultSortType == nsMsgViewSortType::byCustom) {
     *aDefaultSortType = nsMsgViewSortType::byDate;
   }
   return NS_OK;
